import curses
import random
import time

def main(stdscr):
    curses.curs_set(0)
    stdscr.nodelay(1)
    stdscr.timeout(100)

    snake = [(0, 0)]
    direction = curses.KEY_RIGHT
    food = random.choice([(i, j) for i in range(-10, 11) for j in range(-10, 11) if (i, j) != (0, 0)])
    score = 0

    def draw_snake(snake):
        for pos in snake:
            stdscr.addch(pos[0], pos[1], curses.ACS_CKBOARD)

    def draw_food(food):
        stdscr.addch(food[0], food[1], curses.ACS_PI)

    def move_snake(snake, direction):
        head = snake[0]
        new_head = (head[0] + direction[0], head[1] + direction[1])
        if new_head == food:
            score += 1
            food = random.choice([(i, j) for i in range(-10, 11) for j in range(-10, 11) if (i, j) != (0, 0)])
        else:
            snake.pop()
        snake.insert(0, new_head)
        return snake

    def check_bounds(snake):
        for pos in snake:
            if not (-10 <= pos[0] <= 10 and -10 <= pos[1] <= 10):
                return True
        return False

    def handle_input(stdscr):
        while True:
            key = stdscr.getch()
            if key == ord('q'):
                return
            elif key == curses.KEY_UP and direction != curses.KEY_DOWN:
                direction = curses.KEY_UP
            elif key == curses.KEY_DOWN and direction != curses.KEY_UP:
                direction = curses.KEY_DOWN
            elif key == curses.KEY_LEFT and direction != curses.KEY_RIGHT:
                direction = curses.KEY_LEFT
            elif key == curses.KEY_RIGHT and direction != curses.KEY_LEFT:
                direction = curses.KEY_RIGHT

    def game_loop():
        while True:
            handle_input(stdscr)
            snake = move_snake(snake, direction)
            if check_bounds(snake):
                stdscr.addstr(0, 0, "Game Over! Score: {}".format(score))
                break
            draw_snake(snake)
            draw_food(food)
            stdscr.refresh()
            time.sleep(0.1)

    game_loop()

if __name__ == "__main__":
    curses.wrapper(main)

import curses
import random
import time

def main(stdscr):
    curses.curs_set(0)
    stdscr.timeout(100)
    height, width = stdscr.getmaxyx()
    snake = [(height // 2, width // 2)]
    direction = curses.KEY_RIGHT
    food = (random.randint(1, height - 2), random.randint(1, width - 2))
    score = 0

    def draw_snake(snake):
        for pos in snake:
            stdscr.addch(pos[0], pos[1], curses.ACS_CKBOARD)

    def draw_food(food):
        stdscr.addch(food[0], food[1], curses.ACS_PI)

    def move_snake(snake, direction):
        head = snake[0]
        new_head = (head[0] + direction[0], head[1] + direction[1])
        if new_head in snake[1:]:
            return False
        if new_head[0] < 1 or new_head[0] >= height or new_head[1] < 1 or new_head[1] >= width:
            return False
        snake.insert(0, new_head)
        if new_head == food:
            score += 1
            food = (random.randint(1, height - 2), random.randint(1, width - 2))
        else:
            snake.pop()
        return True

    def handle_input(stdscr):
        while True:
            key = stdscr.getch()
            if key == ord('q'):
                return
            if key == curses.KEY_UP and direction != curses.KEY_DOWN:
                direction = curses.KEY_UP
            elif key == curses.KEY_DOWN and direction != curses.KEY_UP:
                direction = curses.KEY_DOWN
            elif key == curses.KEY_LEFT and direction != curses.KEY_RIGHT:
                direction = curses.KEY_LEFT
            elif key == curses.KEY_RIGHT and direction != curses.KEY_LEFT:
                direction = curses.KEY_RIGHT

    def game_loop():
        while True:
            draw_snake(snake)
            draw_food(food)
            stdscr.refresh()
            if not move_snake(snake, direction):
                break
            handle_input(stdscr)
            time.sleep(0.1)

    game_loop()

if __name__ == "__main__":
    curses.wrapper(main)
